   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<R and 0<=ny<C and g[nx][ny]==0 and (nx,ny) not in seen: seen.add((nx,ny)); q.append((nx,ny))
   comps.append(comp)
